-- Note: the "Call Me Maybe" question below is written directly in its final,
-- corrected form. The version originally applied to the database had leftover
-- reasoning text baked into the prompt ("...actually British? (trick: name
-- the Canadian instead)...") and was fixed in place with an UPDATE right
-- after this migration ran. This file reflects that fix so a fresh apply
-- reproduces the current, correct database state.

insert into public.questions (prompt, options, correct_index, category, difficulty)
select prompt, options, correct_index, 'Music', difficulty
from (values
