  ('Which singer is known for the alter ego "Sasha Fierce"?', array['Rihanna','Beyonce','Nicki Minaj','Ciara'], 1, 'hard'),
  ('Which classical period composer is known for the "Moonlight Sonata"?', array['Mozart','Beethoven','Chopin','Liszt'], 1, 'medium'),
